create table transcripts (id uuid primary key, episode_id uuid not null references episodes(id) on delete cascade, source_type text not null, source_uri text, language text, status text not null, transcript_version text not null, processing_job_id uuid references processing_jobs(id), created_at timestamptz not null default now(), unique(episode_id,transcript_version));
create table transcript_segments (id uuid primary key, transcript_id uuid not null references transcripts(id) on delete cascade, episode_id uuid not null references episodes(id) on delete cascade, start_ms bigint not null check(start_ms>=0), end_ms bigint not null check(end_ms>start_ms), text text not null, speaker_label text, speaker_confidence numeric(4,3), topics jsonb not null default '[]', entities jsonb not null default '[]', content_type text not null default 'unknown', content_confidence numeric(4,3), source_version text not null);
create table episode_intelligence (id uuid primary key, episode_id uuid not null references episodes(id) on delete cascade, transcript_id uuid not null references transcripts(id) on delete cascade, kind text not null, status text not null, payload jsonb not null, model_provider text, model_version text, pipeline_version text not null, generated_at timestamptz, stale_at timestamptz, unique(episode_id,kind,pipeline_version));
create index transcript_segments_episode_range on transcript_segments(episode_id,start_ms); create index episode_intelligence_episode_kind on episode_intelligence(episode_id,kind,status);
